def solve():
    results = {}

    # Test for n = 1 up to n = 50
    for n in range(1, 51):
        N = 2 * n + 1

        # Calculate the sequence of flip indices P_k = k(k-1)/2 mod N for k=1 to N
        flip_indices = []
        for k in range(1, N + 1):
            # P_k = k * (k - 1) // 2
            # Since k*(k-1) is always even, the division is exact before modulo.
            P_k = (k * (k - 1) // 2) % N
            flip_indices.append(P_k)

        # Calculate the frequency C_j for each index j in {0, ..., N-1}
        counts = {}
        for index in flip_indices:
            counts[index] = counts.get(index, 0) + 1

        # Count how many indices appear an odd number of times
        odd_count = 0
        for j in range(N):
            count_j = counts.get(j, 0)
            if count_j % 2 != 0:
                odd_count += 1

        results[N] = odd_count

    return results

results = solve()
print("N (2n+1) | Number of indices appearing an odd number of times")
print("-" * 50)
for N, count in sorted(results.items()):
    print(f"{N: <7} | {count}")
